exercise.solution:
fn verdict(setting: &str) -> &str {
    match setting {
        s if s.starts_with("pool size 2") => "starvation",
        s if s.starts_with("pool size = workers") => "healthy",
        s if s.contains("no max lifetime") => "stale connections",
        _ => "exhaustion",
    }
}

fn main() {
    for s in [
        "pool size 2 for 50 workers",
        "pool size = workers, idle timeout 5m",
        "no max lifetime on cloud DB",
        "hold connection during slow external API call",
    ] {
        println!("{}: {}", s, verdict(s));
    }
}
